def check(q, mapping, wsize):
	sum = 0
	point = 0
	for i in range(len(q)):
		if point < wsize:
			mapping[q[i]] -= 1
			point += 1
			if mapping[q[i]] == 0:
				sum -= 1
			else:
				sum += 1
		elif sum == wsize:
			return True
		else:
			mapping[q[i - wsize]] += 1
			if mapping[q[i - wsize]] == 1:
				sum += 1
			else:
				sum -= 1
			mapping[q[i]] -= 1
			if mapping[q[i]] == 0:
				sum -= 1
			else:
				sum += 1
	else:
		if sum == wsize:
			return True
		return False

def bsearch(n, m, q, mapping):
	left = n
	right = m
	ans = 0
	while left <= right:
		mid = left + (right - left) // 2
		if check(q, mapping.copy(), m - mid) == True:
			ans = mid
			right = mid - 1
		else:
			left = mid + 1
	return ans
for i in range(int(input())):
	(n, m) = map(int, input().split())
	q = [int(j) for j in input().split()]
	mapping = {j: 0 for j in range(1, n + 1)}
	for j in q:
		mapping[j] += 1
	ans = bsearch(n, m, q, mapping)
	print(ans)
